/* === LAYOUT IMPROVEMENTS === */

/* Container cho header buttons */
.header-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  background: #2D2D2D;
  border-bottom: 1px solid #404040;
  gap: 16px;
}

.header-toolbar-left {
