}

/* Separator giữa các nhóm */
.button-separator {
  width: 1px;
  height: 32px;
  background: #404040;
  margin: 0 8px;
}

/* === ACCESSIBILITY === */

/* Keyboard Navigation */
.header-btn:focus-visible {
  outline: 3px solid #2196F3;
  outline-offset: 2px;
}

/* Screen Reader */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
  .header-btn {
    border: 2px solid currentColor;
  }

  .header-btn .badge {
    border: 2px solid white;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  .header-btn,
