  .btn-alert-delayed {
    animation: none !important;
    transition: none !important;
  }
}

/* Touch Targets (Mobile) */
@media (max-width: 768px) {
  .header-btn {
    min-height: 44px; /* iOS minimum */
    min-width: 44px;
  }
}

